// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract LineTable {
    uint256 public value;

    constructor() {
        value = 1;
    }

    function set(uint256 newValue) public {
        if (newValue == 0) {
            revert();
        }
        value = newValue;
    }
}
